pub fn unsafe_get_current_temperature() -> Isolette_Thermostat_Rust::CurrentTemperature
{
  unsafe {
    let value: *mut Isolette_Thermostat_Rust::CurrentTemperature = &mut Isolette_Thermostat_Rust::CurrentTemperature::default();
    get_current_temperature(value);
    return *value;
  }
}

