#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_current_temperature: Mutex<Option<Isolette_Thermostat_Rust::CurrentTemperature>> = Mutex::new(None);
  pub static ref IN_desired_settings: Mutex<Option<Isolette_Thermostat_Rust::DesiredTemperatureSettings>> = Mutex::new(None);
  pub static ref IN_regulator_mode: Mutex<Option<Isolette_Thermostat_Rust::ThermostatMode>> = Mutex::new(None);
  pub static ref OUT_interface_facts: Mutex<Option<Isolette_Thermostat_Rust::RegulatorInterfaceFacts>> = Mutex::new(None);
  pub static ref OUT_regulator_feedback: Mutex<Option<Isolette_Thermostat_Rust::RegulatorFeedback>> = Mutex::new(None);
  pub static ref OUT_control_basis: Mutex<Option<Isolette_Thermostat_Rust::RegulatorControlBasis>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_current_temperature.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_desired_settings.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_regulator_mode.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_interface_facts.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_regulator_feedback.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_control_basis.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_current_temperature(value: *mut Isolette_Thermostat_Rust::CurrentTemperature) -> bool
{
  unsafe {
    let guard = IN_current_temperature.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

